 * ~150 questions (25 par catégorie)
 */
object QuestionsExpansion3 {
    fun get(): List<Question> = listOf(
        // GÉOGRAPHIE (30001-30025)
        Question(30001, "Quel est la capitale de la Thaïlande ?", listOf("Chiang Mai", "Bangkok", "Phuket", "Ayutthaya"), 1, "Géographie", Difficulty.EASY, explanation = "Bangkok est la capitale et la ville la plus peuplée de Thaïlande, située dans le delta du fleuve Chao Phraya."),
        Question(30002, "En quel continent se trouve la Namibie ?", listOf("Asie", "Océanie", "Afrique", "Amérique du Sud"), 2, "Géographie", Difficulty.EASY, explanation = "La Namibie est un pays situé sur la côte sud-ouest de l'Afrique, bordé par l'océan Atlantique."),
        Question(30003, "Quel océan sépare l'Afrique de l'Australie ?", listOf("Océan Atlantique", "Océan Indien", "Océan Pacifique", "Océan Arctique"), 1, "Géographie", Difficulty.EASY, explanation = "L'océan Indien est le troisième plus grand océan du monde et baigne les côtes orientales de l'Afrique ainsi que les côtes occidentales de l'Australie."),
        Question(30004, "La Nouvelle-Zélande est composée de combien de grandes îles ?", listOf("Une", "Deux", "Trois", "Quatre"), 1, "Géographie", Difficulty.EASY, explanation = "La Nouvelle-Zélande est principalement constituée de deux grandes îles : l'île du Nord et l'île du Sud, séparées par le détroit de Cook."),
        Question(30005, "Quel désert est le plus grand du monde ?", listOf("Kalahari", "Gobi", "Antarctique", "Sahara"), 2, "Géographie", Difficulty.EASY, explanation = "L'Antarctique est considéré comme le plus grand désert du monde car il reçoit très peu de précipitations, moins de 50 mm par an, ce qui correspond à la définition d'un désert."),
        Question(30006, "Quelle est la capitale des Pays-Bas ?", listOf("Rotterdam", "Amsterdam", "La Haye", "Utrecht"), 1, "Géographie", Difficulty.EASY, explanation = "Amsterdam est la capitale constitutionnelle des Pays-Bas, bien que le gouvernement et le parlement siègent à La Haye."),
        Question(30007, "En quel pays se trouve le Kilimandjaro ?", listOf("Kenya", "Ouganda", "Tanzanie", "Zambie"), 2, "Géographie", Difficulty.EASY, explanation = "Le Kilimandjaro, plus haut sommet d'Afrique, est situé dans le nord-est de la Tanzanie, près de la frontière avec le Kenya."),
        Question(30009, "Le fleuve Zambèze est le plus important de quel continent ?", listOf("Asie", "Afrique", "Amérique du Sud", "Europe"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le Zambèze traverse plusieurs pays d'Afrique australe, dont la Zambie et le Zimbabwe, et se jette dans l'océan Indien. C'est le quatrième plus long fleuve du continent."),
        Question(30010, "Quel pays possède le plus grand nombre de lacs au monde ?", listOf("Suède", "Finlande", "Canada", "Norvège"), 2, "Géographie", Difficulty.MEDIUM, explanation = "Le Canada compte environ 60 % des lacs mondiaux, soit plus de 2 millions, en raison de son histoire glaciaire et de son vaste territoire."),
        Question(30011, "En quel année la Singapour s'est-elle indépendante de la Malaisie ?", listOf("1963", "1965", "1967", "1970"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Singapour a été expulsée de la Malaisie le 9 août 1965, devenant ainsi une république indépendante en raison de divergences politiques et économiques."),
        Question(30012, "Quel détroit sépare l'Espagne du Maroc ?", listOf("Détroit de Béring", "Détroit de Gibraltar", "Canal de Suez", "Détroit de Malacca"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le détroit de Gibraltar relie la mer Méditerranée à l'océan Atlantique et marque la frontière naturelle entre l'Europe et l'Afrique, séparant l'Espagne au nord du Maroc au sud."),
        Question(30013, "Quel est le second plus grand désert du monde après l'Antarctique ?", listOf("Sahara", "Arabie", "Atacama", "Gobi"), 1, "Géographie", Difficulty.MEDIUM, explanation = "Le désert d'Arabie s'étend sur environ 2,3 millions de km², ce qui en fait le deuxième plus grand désert chaud du monde après le Sahara, mais derrière l'Antarctique en termes de superficie totale."),
        Question(30014, "En quel continent se trouve la Mongolie ?", listOf("Afrique", "Asie", "Europe", "Océanie"), 1, "Géographie", Difficulty.MEDIUM, explanation = "La Mongolie est située en Asie centrale, entre la Russie et la Chine."),
        Question(30015, "Le fleuve Danube traverse combien de pays ?", listOf("8", "10", "12", "15"), 2, "Géographie", Difficulty.HARD, explanation = "Le Danube traverse 12 pays d'Europe centrale et orientale, de l'Allemagne à la mer Noire, ce qui en fait le fleuve le plus international du monde."),
        Question(30017, "En quel année les Îles Malouines ont-elles fait l'objet d'une guerre entre l'Argentine et la Royaume-Uni ?", listOf("1980", "1982", "1984", "1986"), 1, "Géographie", Difficulty.HARD, explanation = "La guerre des Malouines a opposé l'Argentine au Royaume-Uni en 1982, suite à l'invasion argentine de l'archipel le 2 avril, et s'est conclue par la reddition argentine le 14 juin."),
        Question(30019, "Le Caucase est une chaîne montagneuse partagée par combien de pays ?", listOf("3", "4", "5", "6"), 3, "Géographie", Difficulty.HARD, explanation = "Le Caucase s'étend sur six pays : la Russie, la Géorgie, l'Arménie, l'Azerbaïdjan, la Turquie et l'Iran."),
        Question(30020, "Quel pays possède les plus long côtes au monde ?", listOf("Suède", "Japon", "Canada", "Finlande"), 2, "Géographie", Difficulty.EXPERT, explanation = "Le Canada possède le plus long littoral du monde, s'étendant sur environ 202 080 kilomètres, en raison de ses nombreuses îles et de ses côtes très découpées."),
        Question(30021, "Quel est le point de confluence entre le Tigre et l'Euphrate ?", listOf("Bagdad", "Le Chatt-el-Arab", "Ctésiphon", "Samara"), 1, "Géographie", Difficulty.EXPERT, explanation = "Le Chatt-el-Arab est le fleuve formé par la réunion du Tigre et de l'Euphrate dans le sud de l'Irak, avant de se jeter dans le golfe Persique."),
        Question(30022, "La Mélanésie comprend quels archipels et pays ?", listOf("Fidji, Vanuatu, Îles Salomon, Papouasie-Nouvelle-Guinée", "Samoa, Tonga, Kiribati", "Palau, Micronésie, Marshalls", "Polynésie française, Cook, Tuvalu"), 0, "Géographie", Difficulty.EXPERT, explanation = "La Mélanésie est une région du Pacifique Sud dont le nom signifie « îles noires » en référence à la peau de ses habitants. Elle regroupe notamment la Papouasie-Nouvelle-Guinée, les Îles Salomon, Vanuatu et Fidji."),
        Question(30023, "Quel est le point le plus profond de l'océan Pacifique ?", listOf("Fosse des Aléoutiennes", "Fosse de Kuril-Kamtchatka", "Fosse de Mariannes", "Fosse du Pérou"), 2, "Géographie", Difficulty.EXPERT, explanation = "La fosse des Mariannes, située dans l'ouest de l'océan Pacifique, atteint environ 11 034 mètres de profondeur à son point le plus bas, appelé le Challenger Deep."),
        Question(30024, "En quel année la partition de l'Inde et du Pakistan a-t-elle eu lieu ?", listOf("1945", "1947", "1950", "1952"), 1, "Géographie", Difficulty.EXPERT, explanation = "La partition de l'Inde et du Pakistan a eu lieu en 1947, marquant la fin de la domination britannique et la création de deux États indépendants."),
        Question(30025, "Le Caucasus est divisé en combien de sous-régions géographiques principales ?", listOf("Deux", "Trois", "Quatre", "Cinq"), 1, "Géographie", Difficulty.EXPERT, explanation = "Le Caucase est traditionnellement divisé en trois sous-régions : le Caucase du Nord, le Caucase central et le Caucase du Sud, selon des critères géographiques et culturels."),

        // SPORT (30026-30050)
        Question(30026, "En quel sport pratique-t-on le cricket ?", listOf("Tennis", "Baseball", "Cricket est un sport à part entière", "Badminton"), 2, "Sport", Difficulty.EASY, explanation = "Le cricket est un sport d'équipe avec ses propres règles, originaire d'Angleterre, et non une variante d'un autre sport."),
        Question(30027, "Quel pays a remporté la Coupe du Monde 2022 ?", listOf("France", "Argentine", "Brésil", "Allemagne"), 1, "Sport", Difficulty.EASY, explanation = "L'Argentine a remporté la Coupe du Monde 2022 au Qatar en battant la France en finale aux tirs au but, offrant à Lionel Messi son premier titre mondial."),
        Question(30028, "En quel année les premiers Jeux Olympiques modernes ont-ils eu lieu ?", listOf("1890", "1896", "1900", "1904"), 1, "Sport", Difficulty.EASY, explanation = "Organisés par Pierre de Coubertin, les premiers Jeux Olympiques modernes se sont tenus à Athènes en 1896, marquant le renouveau de la tradition antique."),
        Question(30029, "Quel sport martial japonais se joue sur un tatami ?", listOf("Karaté", "Judo", "Kendo", "Taekwondo"), 1, "Sport", Difficulty.EASY, explanation = "Le judo, comme le karaté ou l'aïkido, se pratique sur un tatami, un tapis de sol traditionnel qui amortit les chutes et délimite l'aire de combat."),
        Question(30030, "Combien de sets faut-il gagner pour remporter un match de tennis en Grand Chelem ?", listOf("Un", "Deux", "Trois", "Quatre"), 2, "Sport", Difficulty.EASY, explanation = "Dans les tournois du Grand Chelem, les matchs masculins se jouent au meilleur des cinq sets, tandis que les matchs féminins se jouent au meilleur des trois sets. Il faut donc gagner trois sets pour remporter un match masculin."),
        Question(30031, "En quel pays se déroule le tournoi de Wimbledon ?", listOf("États-Unis", "France", "Royaume-Uni", "Australie"), 2, "Sport", Difficulty.EASY, explanation = "Wimbledon se déroule à Londres, au Royaume-Uni, depuis 1877. C'est le plus ancien tournoi de tennis au monde."),
        Question(30032, "Quel sport traditionnel japonais met en scène des lutteurs géants appelés rikishi ?", listOf("Karaté", "Sumo", "Kendo", "Judo"), 1, "Sport", Difficulty.EASY, explanation = "Le sumo est un sport de combat rituel japonais où des lutteurs de très forte corpulence, les rikishi, s'affrontent dans un cercle de terre battue."),
        Question(30033, "En quel année le football a-t-il été intégré aux Jeux Olympiques modernes ?", listOf("1900", "1908", "1920", "1936"), 2, "Sport", Difficulty.MEDIUM, explanation = "Le football masculin a été intégré aux Jeux Olympiques modernes en 1900, mais en tant que sport de démonstration. Il est devenu une compétition officielle avec médailles à partir des Jeux d'Anvers en 1920."),
        Question(30035, "Quel lutteur de WWE est devenu acteur à Hollywood ?", listOf("John Cena", "Dwayne \"The Rock\" Johnson", "les deux", "Aucun des deux"), 2, "Sport", Difficulty.MEDIUM, explanation = "Dwayne Johnson (The Rock) et John Cena sont les deux lutteurs WWE les plus célèbres à avoir réussi une carrière d'acteur à Hollywood, avec des rôles majeurs dans des films à succès."),
        Question(30036, "En quel année Cristiano Ronaldo a-t-il remporté son cinquième Ballon d'Or ?", listOf("2017", "2018", "2019", "2020"), 2, "Sport", Difficulty.MEDIUM, explanation = "Cristiano Ronaldo a remporté son cinquième Ballon d'Or en 2019, égalant alors le record de Lionel Messi. Il a été récompensé pour ses performances avec la Juventus et le Portugal."),
        Question(30037, "Quel pays domine le badminton moderne avec le plus de champions olympiques ?", listOf("Malaisie", "Indonésie", "Chine", "Danemark"), 2, "Sport", Difficulty.MEDIUM, explanation = "La Chine domine le badminton olympique grâce à un système d'entraînement rigoureux et une culture sportive forte, totalisant le plus grand nombre de médailles d'or dans cette discipline depuis son introduction aux Jeux en 1992."),
        Question(30038, "En quel année le premier Grand Prix de Formule 1 a-t-il eu lieu ?", listOf("1946", "1950", "1954", "1960"), 1, "Sport", Difficulty.MEDIUM, explanation = "Le premier championnat du monde de Formule 1 a été organisé par la FIA en 1950, avec le Grand Prix de Grande-Bretagne à Silverstone comme course inaugurale le 13 mai."),
        Question(30039, "Quel boxeur a changé son nom en Muhammad Ali ?", listOf("Floyd Patterson", "Sonny Liston", "Cassius Clay", "Joe Frazier"), 2, "Sport", Difficulty.HARD, explanation = "Cassius Clay a changé son nom pour Muhammad Ali après sa conversion à l'islam et son adhésion à la Nation of Islam en 1964."),
        Question(30040, "En quel année LeBron James a-t-il été drafté en NBA ?", listOf("2002", "2003", "2004", "2005"), 2, "Sport", Difficulty.HARD, explanation = "LeBron James a été sélectionné en première position de la draft NBA en 2003 par les Cleveland Cavaliers, et non en 2004."),
        Question(30041, "Quel joueur de cricket indien est connu comme le \"Dieu du Cricket\" ?", listOf("Virat Kohli", "Sachin Tendulkar", "Anil Kumble", "Rohit Sharma"), 1, "Sport", Difficulty.HARD, explanation = "Sachin Tendulkar est considéré comme le plus grand batteur de l'histoire du cricket, avec des records mondiaux exceptionnels et une carrière de 24 ans."),
        Question(30042, "En quel année a eu lieu la première Coupe du Monde de cricket ?", listOf("1975", "1979", "1983", "1987"), 0, "Sport", Difficulty.HARD, explanation = "La première Coupe du Monde de cricket s'est déroulée en Angleterre en 1975, sous le nom de Prudential Cup, avec huit équipes participantes."),
        Question(30043, "Quel Grand Chelem de tennis est joué sur court en terre battue rouge ?", listOf("Wimbledon", "Open d'Australie", "Roland-Garros", "US Open"), 2, "Sport", Difficulty.HARD, explanation = "Roland-Garros, aussi appelé Internationaux de France, est le seul tournoi du Grand Chelem à se disputer sur terre battue, une surface en brique pilée qui ralentit la balle et favorise les échanges longs."),
        Question(30044, "En quel année le tournament de Sumo le plus ancien a-t-il commencé ?", listOf("1909", "1925", "1950", "1960"), 1, "Sport", Difficulty.EXPERT, explanation = "Le tournoi de sumo le plus ancien, le Grand Tournoi de Printemps à Osaka, a débuté en 1925, marquant le début des compétitions modernes organisées par l'Association japonaise de sumo."),
        Question(30045, "Quel sport d'équipe brésilien est similaire au volleyball mais joué sur sable ?", listOf("Futsal", "Footvolley", "Altinha", "Frescobol"), 2, "Sport", Difficulty.EXPERT, explanation = "L'Altinha est un sport brésilien qui se joue sur le sable, souvent sur les plages, avec un ballon de football et sans filet, où les joueurs doivent garder le ballon en l'air en utilisant toutes les parties du corps sauf les mains."),
        Question(30046, "En quel année Usain Bolt a-t-il établi le record du monde du 100m (9.58s) ?", listOf("2008", "2009", "2011", "2012"), 3, "Sport", Difficulty.EXPERT, explanation = "Usain Bolt a établi ce record du monde lors des championnats du monde d'athlétisme à Berlin en 2009, et non en 2012."),
        Question(30047, "Quel joueur de cricket australien a pris le plus grand nombre de guichets en test cricket ?", listOf("Shane Warne", "Brett Lee", "Glenn McGrath", "Dennis Lillee"), 0, "Sport", Difficulty.EXPERT, explanation = "Shane Warne, légendaire spinner australien, détient le record du plus grand nombre de guichets en test cricket pour son pays, avec 708 wickets entre 1992 et 2007."),
        Question(30048, "En quel année la Formule E a-t-elle tenu sa première course officielle ?", listOf("2012", "2013", "2014", "2015"), 2, "Sport", Difficulty.EXPERT, explanation = "La FIA a lancé la Formule E en 2014 pour promouvoir les voitures électriques, avec la première course à Pékin en septembre de cette année-là."),
        Question(30049, "Quel tournoi de tennis est le seul à se jouer sur court en béton poreux aux États-Unis ?", listOf("Roland-Garros", "US Open", "Wimbledon", "Open d'Australie"), 1, "Sport", Difficulty.EXPERT, explanation = "L'US Open est le seul tournoi du Grand Chelem à se jouer sur surface dure, et plus précisément sur un revêtement en béton poreux appelé DecoTurf, depuis 1978."),
        Question(30050, "En quel année Tiger Woods a-t-il remporté son 15e major de golf ?", listOf("2019", "2020", "2021", "2022"), 0, "Sport", Difficulty.EXPERT, explanation = "Tiger Woods a remporté son 15e tournoi majeur au Masters d'Augusta en 2019, mettant fin à une disette de 11 ans sans victoire dans un majeur."),

        // MUSIQUE (30051-30075)
        Question(30051, "De quel pays d'Asie vient le K-pop ?", listOf("Japon", "Corée du Sud", "Thaïlande", "Vietnam"), 1, "Musique", Difficulty.EASY, explanation = "Le terme K-pop signifie Korean pop, et ce genre musical est originaire de Corée du Sud, où il a émergé dans les années 1990."),
        Question(30052, "Quel est le genre musical né à la Jamaïque au milieu du 20e siècle ?", listOf("Reggae", "Calypso", "Dancehall", "Ska"), 0, "Musique", Difficulty.EASY, explanation = "Le reggae est né en Jamaïque dans les années 1960, issu du ska et du rocksteady, et popularisé mondialement par des artistes comme Bob Marley."),
        Question(30053, "Quel musicien afrobeat nigérian s'appelle \"Fela\" ?", listOf("Fela Kuti", "Ginger Baker", "Tony Allen", "King Sunny Ade"), 0, "Musique", Difficulty.EASY, explanation = "Fela Kuti, de son nom complet Fela Anikulapo Kuti, est le pionnier du genre afrobeat dans les années 1970 au Nigeria."),
        Question(30054, "De quel pays d'Asie vient la musique classique indienne traditionnelle ?", listOf("Inde", "Thaïlande", "Indonésie", "Malaisie"), 0, "Musique", Difficulty.EASY, explanation = "La musique classique indienne traditionnelle, avec ses deux grandes traditions (hindoustanie et carnatique), est originaire du sous-continent indien, aujourd'hui principalement l'Inde."),
        Question(30055, "Quel est le genre musical latino-américain caractérisé par un rythme rapide et dansant ?", listOf("Bossa nova", "Reggaeton", "Samba", "Tango"), 2, "Musique", Difficulty.EASY, explanation = "La samba est un genre musical brésilien né dans les favelas de Rio de Janeiro, connu pour son rythme syncopé et rapide qui accompagne les défilés du carnaval."),
        Question(30056, "En quel pays la bossa nova s'est-elle développée ?", listOf("Colombie", "Brésil", "Pérou", "Argentine"), 1, "Musique", Difficulty.EASY, explanation = "La bossa nova est un genre musical né au Brésil dans les années 1950, mêlant samba et jazz, popularisé par des artistes comme João Gilberto et Antônio Carlos Jobim."),
        Question(30057, "Quel genre de musique provient d'un mélange de rythmes africains et de mélodies latino-américaines ?", listOf("Afrobeat", "Samba", "Rumba", "Tango"), 0, "Musique", Difficulty.EASY, explanation = "L'afrobeat est un genre musical né au Nigeria dans les années 1960, créé par Fela Kuti, fusionnant des rythmes traditionnels africains avec des influences de jazz, funk et de musique latino-américaine."),
        Question(30058, "Quel pays a produit le plus de hits reggaeton à l'échelle mondiale ?", listOf("Mexique", "Colombie", "Porto Rico", "République Dominicaine"), 2, "Musique", Difficulty.MEDIUM, explanation = "Porto Rico est considéré comme le berceau et l'épicentre du reggaeton moderne, avec des artistes comme Daddy Yankee, Bad Bunny et Nicky Jam qui dominent les classements mondiaux."),
        Question(30059, "En quel année Psy a-t-il lancé \"Gangnam Style\" ?", listOf("2010", "2011", "2012", "2013"), 2, "Musique", Difficulty.MEDIUM, explanation = "Le tube \"Gangnam Style\" du chanteur sud-coréen Psy est sorti en juillet 2012, devenant un phénomène viral mondial et la première vidéo YouTube à atteindre un milliard de vues."),
        Question(30060, "Quel groupe de K-pop a remporté l'Award de meilleur groupe à la cérémonie des MTV Video Music Awards 2020 ?", listOf("Blackpink", "BTS", "EXO", "Stray Kids"), 1, "Musique", Difficulty.MEDIUM, explanation = "BTS a remporté le prix du meilleur groupe aux MTV Video Music Awards 2020 pour leur performance de \"Dynamite\", marquant une reconnaissance majeure de la K-pop aux États-Unis."),
        Question(30061, "En quel année la bossa nova s'est-elle popularisée internationalement avec \"Girl from Ipanema\" ?", listOf("1960", "1962", "1964", "1966"), 1, "Musique", Difficulty.MEDIUM, explanation = "La version de \"Garota de Ipanema\" par Stan Getz et João Gilberto, sortie en 1962, a propulsé la bossa nova sur la scène mondiale."),
        Question(30062, "Quel artiste afrobeat nigérian a collaboré avec Paul McCartney ?", listOf("Fela Kuti", "King Sunny Ade", "Burna Boy", "Davido"), 0, "Musique", Difficulty.MEDIUM, explanation = "Fela Kuti, pionnier de l'afrobeat, a collaboré avec Paul McCartney en 1973 sur l'album \"London Scene\", bien que McCartney ait été arrêté avec lui pour possession de cannabis."),
        Question(30063, "Quel instrument est central à la musique classique indienne pour l'imprimerie ?", listOf("Sitar", "Tabla", "Sarod", "Bansuri"), 0, "Musique", Difficulty.MEDIUM, explanation = "Le sitar est un instrument à cordes pincées emblématique de la musique classique indienne, notamment utilisé dans la tradition hindoustanie du Nord de l'Inde."),
        Question(30064, "De quel pays provient le reggaeton moderne en tant que genre ?", listOf("Jamaïque", "Trinité-et-Tobago", "Porto Rico", "République Dominicaine"), 2, "Musique", Difficulty.HARD, explanation = "Le reggaeton moderne est né à Porto Rico dans les années 1990, fusionnant le reggae jamaïcain, le dancehall et le hip-hop avec des rythmes latins."),
        Question(30065, "Quel musicien brésilien est connu comme \"O Rei da Bossa Nova\" (Le Roi de la Bossa Nova) ?", listOf("Antônio Carlos Jobim", "João Gilberto", "Stan Getz", "Vinícius de Moraes"), 1, "Musique", Difficulty.HARD, explanation = "João Gilberto est surnommé \"O Rei da Bossa Nova\" pour avoir révolutionné la musique brésilienne en créant le style bossa nova, notamment avec son album \"Chega de Saudade\" en 1959."),
        Question(30066, "En quel année Bollywood a-t-elle lancé le genre du \"Item Number\" popularisé par danseuses ?", listOf("1960s", "1970s", "1980s", "1990s"), 1, "Musique", Difficulty.HARD, explanation = "Le terme \"Item Number\" a émergé dans le cinéma indien des années 1970 avec des chansons dansées par des actrices vedettes comme Helen, popularisant ce genre de performance glamour et autonome."),
        Question(30067, "Quel artiste J-pop s'appelle Utada Hikaru et a remporté plusieurs Grammy Awards ?", listOf("Vrai", "Faux", "Partiellement vrai", "Inconnu"), 1, "Musique", Difficulty.HARD, explanation = "Utada Hikaru n'a jamais remporté de Grammy Awards, bien qu'elle soit une artiste J-pop célèbre. Ses récompenses incluent des Japan Gold Disc Awards et des MTV Video Music Awards Japan."),
        Question(30068, "Quel groupe de hip-hop sud-coréen a révolutionné le genre en Asie avec des lyrics en coréen ?", listOf("Tiger JK", "Epik High", "Jay Park", "Drunken Tiger"), 3, "Musique", Difficulty.HARD, explanation = "Drunken Tiger, formé en 1999 par Tiger JK, a été le premier groupe de hip-hop sud-coréen à rapper en coréen, ouvrant la voie à la vague K-hip-hop en Asie."),
        Question(30069, "En quel année les Beatles ont-ils enregistré \"Norwegian Wood\" inspirée par la musique indienne ?", listOf("1964", "1965", "1966", "1967"), 2, "Musique", Difficulty.EXPERT, explanation = "Les Beatles ont enregistré \"Norwegian Wood\" en 1965 pour l'album \"Rubber Soul\", mais c'est en 1966 qu'ils ont exploré plus profondément la musique indienne, notamment avec George Harrison jouant du sitar."),
        Question(30070, "Quel maestro sud-africain est connu pour sa fusion entre la musique traditionnelle et le jazz ?", listOf("Miriam Makeba", "Abdullah Ibrahim", "Hugh Masekela", "Caiphus Semenya"), 1, "Musique", Difficulty.EXPERT, explanation = "Abdullah Ibrahim, pianiste et compositeur sud-africain, mêle les rythmes traditionnels de son pays, comme le marabi, avec le jazz, notamment sur son album emblématique \"African Marketplace\"."),
        Question(30071, "En quel année le premier album de BTS \"2 Cool 4 Skool\" a-t-il été lancé ?", listOf("2011", "2012", "2013", "2014"), 2, "Musique", Difficulty.EXPERT, explanation = "2 Cool 4 Skool est le premier album du groupe sud-coréen BTS, sorti le 12 juin 2013, marquant leurs débuts officiels dans l'industrie musicale."),
        Question(30072, "Quel compositeur indien a remporté un Oscar pour sa musique de film ?", listOf("Ravi Shankar", "A.R. Rahman", "Anu Malik", "Ilayaraja"), 1, "Musique", Difficulty.EXPERT, explanation = "A.R. Rahman a remporté l'Oscar de la meilleure musique de film en 2009 pour la bande originale de Slumdog Millionaire."),
        Question(30073, "Quel pays produit le plus haut taux de consommation de musique classique arabe par habitant ?", listOf("Liban", "Égypte", "Syrie", "Irak"), 0, "Musique", Difficulty.EXPERT, explanation = "Le Liban a une longue tradition de musique classique arabe, avec des figures emblématiques comme Fairuz et des institutions culturelles actives, ce qui en fait le plus grand consommateur par habitant."),
        Question(30074, "En quel année Fela Kuti a-t-il enregistré \"Zombie\" critique du régime militaire nigérian ?", listOf("1972", "1974", "1976", "1978"), 1, "Musique", Difficulty.EXPERT, explanation = "Fela Kuti a enregistré l'album \"Zombie\" en 1974, une satire féroce des soldats nigérians qu'il comparait à des zombies obéissant aveuglément aux ordres. Cette critique du régime militaire lui a valu des représailles violentes, notamment l'incendie de sa commune par l'armée."),
        Question(30075, "Quel producteur français a popularisé la \"touch française\" en hip-hop avec Daft Punk et Justice ?", listOf("Rodney Jerkins", "Timbaland", "Neptunes", "Brainfeeder"), 2, "Musique", Difficulty.EXPERT, explanation = "Les Neptunes sont un duo de producteurs américains, pas français. La \"touch française\" en hip-hop a été popularisée par des producteurs français comme ceux de Daft Punk et Justice, mais le terme désigne un style électronique français, pas un duo américain."),

        // CULTURE (30076-30100)
        Question(30076, "En quel mois se déroule traditionnellement Diwali en Inde ?", listOf("Août", "Septembre", "Octobre-Novembre", "Décembre"), 2, "Culture", Difficulty.EASY, explanation = "Diwali, la fête des lumières, suit le calendrier lunaire hindou et tombe généralement entre mi-octobre et mi-novembre, pendant le mois d’Ashvin ou Kartik."),
        Question(30077, "Quel est le nom du festival des fleurs de cerisier au Japon ?", listOf("Tanabata", "Hanami", "Obon", "Setsubun"), 1, "Culture", Difficulty.EASY, explanation = "Hanami est le nom donné à la tradition japonaise d'admirer les fleurs de cerisier, qui est aussi un festival printanier célébrant leur floraison éphémère."),
        Question(30078, "En quel pays se déroule le Carnaval de Rio ?", listOf("Porto Rico", "Brésil", "Haïti", "Jamaïque"), 1, "Culture", Difficulty.EASY, explanation = "Le Carnaval de Rio se déroule au Brésil, dans la ville de Rio de Janeiro. C'est l'un des plus grands carnavals du monde, connu pour ses défilés de samba et ses costumes spectaculaires."),
        Question(30079, "Quel festival indien célèbre-t-on avec des poudres colorées et de l'eau ?", listOf("Diwali", "Navratri", "Holi", "Pongal"), 2, "Culture", Difficulty.EASY, explanation = "Holi est une fête hindoue du printemps qui symbolise la victoire du bien sur le mal. Les participants se jettent des poudres et de l'eau colorées pour célébrer la joie et la renaissance."),
        Question(30080, "En quel pays se célèbre la Fête des Morts (Día de los Muertos) au 1er novembre ?", listOf("Bolivie", "Pérou", "Mexique", "Colombie"), 2, "Culture", Difficulty.EASY, explanation = "Le Día de los Muertos est une tradition mexicaine qui honore les défunts, mêlant croyances préhispaniques et catholicisme. Elle est célébrée les 1er et 2 novembre, dates correspondant à la Toussaint."),
        Question(30081, "Quel mois célèbre-t-on le Nouvel An chinois (Chinese New Year) ?", listOf("Janvier", "Janvier-Février", "Février", "Mars"), 1, "Culture", Difficulty.EASY, explanation = "Le Nouvel An chinois suit le calendrier lunaire, dont la date varie entre le 21 janvier et le 20 février. Il commence à la deuxième nouvelle lune après le solstice d'hiver."),
        Question(30082, "En quel pays se déroule le festival Oktoberfest ?", listOf("Autriche", "Suisse", "Allemagne", "Belgique"), 2, "Culture", Difficulty.EASY, explanation = "L'Oktoberfest est une fête populaire traditionnelle qui se tient chaque année à Munich, en Bavière, dans le sud de l'Allemagne."),
        Question(30083, "Quel festival africain célèbre la culture et l'unité pan-africaine en Afrique du Sud ?", listOf("Essence Festival", "Africolor", "Afrochella", "Pan-African Film Festival"), 2, "Culture", Difficulty.MEDIUM, explanation = "Afrochella, organisé au Cap, est un festival de musique et de mode qui célèbre la culture africaine contemporaine et promeut l'unité pan-africaine."),
        Question(30084, "En quel année le Ramadan a-t-il commencé en tant que mois de jeûne musulman ?", listOf("632 AD", "610 AD", "630 AD", "650 AD"), 0, "Culture", Difficulty.MEDIUM, explanation = "Le jeûne du Ramadan a été institué en l’an 632 de notre ère, correspondant à la deuxième année de l’Hégire, lorsque le prophète Mahomet a reçu la révélation coranique ordonnant cette pratique."),
        Question(30085, "Quel est le nom du nouvel an thai célébré en avril ?", listOf("Loy Krathong", "Songkran", "Phimai", "Phanom Rung"), 1, "Culture", Difficulty.MEDIUM, explanation = "Songkran est le Nouvel An traditionnel thaïlandais, célébré du 13 au 15 avril, marqué par des batailles d'eau symbolisant la purification et le renouveau."),
        Question(30086, "En quel pays se célèbre la fête de Navratri pendant 9 nuits avec danses Garba ?", listOf("Sri Lanka", "Inde", "Népal", "Bhoutan"), 1, "Culture", Difficulty.MEDIUM, explanation = "Navratri est une fête hindoue majeure célébrée en Inde, où les danses Garba et Dandiya Raas sont exécutées pendant neuf nuits en l'honneur de la déesse Durga."),
        Question(30087, "Quel festival brésilien célèbre la diversité culturelle et les traditions autochtones ?", listOf("Festa de Santo Antônio", "Festa de São João", "Bumba Meu Boi", "Festa de Nossa Senhora"), 2, "Culture", Difficulty.MEDIUM, explanation = "Le Bumba Meu Boi est un festival folklorique brésilien du Nordeste qui met en scène des danses, musiques et costumes inspirés des cultures indigènes, africaines et portugaises."),
        Question(30088, "En quel mois se déroule Holi, le festival des couleurs en Inde ?", listOf("Décembre", "Janvier", "Février-Mars", "Mai"), 2, "Culture", Difficulty.HARD, explanation = "Holi est une fête hindoue qui marque l'arrivée du printemps et la victoire du bien sur le mal. Elle a lieu à la pleine lune du mois de Phalguna, qui correspond à février-mars dans le calendrier grégorien."),
        Question(30089, "Quel festival sikh signe la récolte et l'arrivée du printemps ?", listOf("Diwali", "Baisakhi", "Lohri", "Hola Mohalla"), 1, "Culture", Difficulty.HARD, explanation = "Baisakhi est une fête sikh qui marque à la fois la récolte du blé et le début du printemps, célébrée principalement au Pendjab."),
        Question(30090, "En quel pays se déroule la Fête de la Musique (\"Fête de la Musique\") le 21 juin ?", listOf("Belgique", "France", "Suisse", "Canada"), 1, "Culture", Difficulty.HARD, explanation = "La Fête de la Musique a été créée en France en 1982 par le ministère de la Culture, et elle est célébrée chaque 21 juin dans tout le pays."),
        Question(30091, "Quel festival islandais célèbre le solstice d'été avec des concerts et des événements ?", listOf("Reykjavik Blues Festival", "Secret Solstice", "Þjóðlega", "Aldrei for eg Sumar"), 1, "Culture", Difficulty.HARD, explanation = "Secret Solstice est un festival de musique islandais qui se tient chaque année en juin, profitant du soleil de minuit pour proposer des concerts et événements autour du solstice d'été."),
        Question(30092, "En quel année le Festival de Cannes a-t-il commencé pour la première fois ?", listOf("1946", "1948", "1950", "1952"), 0, "Culture", Difficulty.HARD, explanation = "Le Festival de Cannes devait initialement avoir lieu en 1939, mais a été annulé à cause du déclenchement de la Seconde Guerre mondiale. Il s'est finalement tenu pour la première fois en 1946."),
        Question(30093, "Quel festival honore les ancêtres morts au Japon pendant l'Obon ?", listOf("Gion Matsuri", "Awa Odori", "Obon Odori", "Takayama Matsuri"), 2, "Culture", Difficulty.EXPERT, explanation = "L'Obon est une tradition bouddhiste japonaise pour honorer les esprits des ancêtres, et l'Obon Odori est une danse folklorique exécutée lors de ce festival pour les accueillir."),
        Question(30094, "En quel pays se déroule la fête de La Tomatina, une bataille de tomates ?", listOf("Italie", "Espagne", "Portugal", "Grèce"), 1, "Culture", Difficulty.EXPERT, explanation = "La Tomatina a lieu chaque année à Buñol, en Espagne, depuis 1945. Cette tradition est devenue un événement touristique mondialement connu."),
        Question(30095, "Quel festival sud-coréen célèbre la culture pop et l'art électronique ?", listOf("Seoul Jazz Festival", "Korea Queer Film Festival", "Busan International Film Festival", "Ultra Music Festival Korea"), 2, "Culture", Difficulty.EXPERT, explanation = "Le Busan International Film Festival est un événement majeur dédié au cinéma asiatique et international, mais il ne célèbre pas spécifiquement la culture pop et l'art électronique."),
        Question(30096, "En quel pays célèbre-t-on Beltane, un festival celtique ancien marquant le début de l'été ?", listOf("Irlande", "Écosse", "Pays de Galles", "Angleterre"), 1, "Culture", Difficulty.EXPERT, explanation = "Beltane est une fête celtique traditionnellement célébrée en Écosse, ainsi que dans d'autres régions celtiques comme l'Irlande, pour marquer le début de l'été."),
        Question(30097, "Quel festival marocain honore les traditions berbères avec musique et danse ?", listOf("Gnaoua World Music", "Timitar", "Festival de Fès", "Moussem de Tanouda"), 1, "Culture", Difficulty.EXPERT, explanation = "Timitar, qui signifie \"signes\" en berbère, est un festival annuel à Agadir dédié à la musique et à la danse amazighes, mettant en valeur les traditions berbères du Maroc."),
        Question(30098, "En quel année a eu lieu la première édition du Festival de Glastonbury en Angleterre ?", listOf("1970", "1971", "1972", "1973"), 0, "Culture", Difficulty.EXPERT, explanation = "Le premier festival de Glastonbury, alors appelé Pilton Pop, Blues & Folk Festival, s'est tenu en 1970, un jour après la mort de Jimi Hendrix, avec environ 1 500 spectateurs."),
        Question(30099, "Quel festival chinois marque l'anniversaire du Bouddha Goutama avec des processions ?", listOf("Fête du Bateau-Dragon", "Fête des Lanternes", "Fête de la Mid-Autumn", "Vesak"), 3, "Culture", Difficulty.EXPERT, explanation = "Vesak, aussi appelé Wesak, est le festival bouddhiste le plus important, célébré en Asie du Sud-Est et en Chine, commémorant la naissance, l'illumination et la mort de Bouddha Goutama. Les processions et lanternes sont des éléments clés de cette fête."),
        Question(30100, "En quel pays le Carnival of Trinidad and Tobago est-il célébré avec des costumes colorés ?", listOf("Jamaïque", "Haïti", "Trinidad-et-Tobago", "Barbade"), 2, "Culture", Difficulty.EXPERT, explanation = "Le carnaval est une fête nationale à Trinidad-et-Tobago, célèbre pour ses défilés de costumes élaborés et sa musique calypso. Il se déroule juste avant le Carême."),

        // GASTRONOMIE (30101-30125)
        Question(30101, "En quel pays le sushi est-il originaire ?", listOf("Chine", "Japon", "Corée", "Thaïlande"), 1, "Gastronomie", Difficulty.EASY, explanation = "Le sushi est un plat traditionnel japonais à base de riz vinaigré accompagné de poisson cru ou d'autres ingrédients. Ses origines remontent au Japon, où il a évolué à partir de méthodes de conservation du poisson."),
        Question(30102, "Quel est le plat brésilien traditionnel fait de haricots noirs et de porc ?", listOf("Moqueca", "Feijoada", "Pão de Queijo", "Brigadeiro"), 1, "Gastronomie", Difficulty.EASY, explanation = "La feijoada est un ragoût de haricots noirs et de viande de porc, considéré comme le plat national du Brésil, hérité des traditions culinaires portugaises et africaines."),
        Question(30103, "En quel pays le curry est-il un plat traditionnel emblématique ?", listOf("Thaïlande", "Malaisie", "Inde", "Vietnam"), 2, "Gastronomie", Difficulty.EASY, explanation = "Le curry est un mélange d'épices originaire du sous-continent indien, où il est utilisé dans de nombreux plats traditionnels depuis des siècles."),
        Question(30104, "Quel aliment mexicain traditionnel est préparé à partir de masa (pâte de maïs) ?", listOf("Enchilada", "Tamales", "Tacos", "Tous les trois"), 3, "Gastronomie", Difficulty.EASY, explanation = "Les tacos, les tamales et les gorditas sont tous préparés à partir de masa, une pâte de maïs nixtamalisée, ingrédient de base de la cuisine mexicaine."),
        Question(30105, "En quel pays le pho (soupe de nouilles) est-il le plat national ?", listOf("Thaïlande", "Vietnam", "Laos", "Cambodge"), 1, "Gastronomie", Difficulty.EASY, explanation = "Le pho est une soupe de nouilles emblématique originaire du Nord du Vietnam, devenue un symbole culinaire national et un incontournable de la street food vietnamienne."),
        Question(30106, "Quel est le condiment espagnol traditionnel à base de tomates broyées et d'ail ?", listOf("Gazpacho", "Salsa", "Paella", "Tortilla"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le gazpacho est une soupe froide andalouse traditionnellement préparée avec des tomates broyées, de l'ail, du pain, de l'huile d'olive et du vinaigre."),
        Question(30107, "En quel pays les momos (boulettes fourrées) sont-elles un aliment populaire ?", listOf("Inde", "Népal et Tibet", "Japon", "Thaïlande"), 1, "Gastronomie", Difficulty.EASY, explanation = "Les momos sont originaires du Tibet et du Népal, où ils sont un plat de rue emblématique, souvent farcis de viande ou de légumes et cuits à la vapeur."),
        Question(30108, "Quel plat italien traditionnel est à base de risotto et de safran ?", listOf("Lasagne", "Risotto alla Milanese", "Osso Buco", "Polenta"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Le risotto alla Milanese est un plat typique de Milan, dont la couleur jaune et le goût distinctif viennent du safran, une épice précieuse utilisée dans la cuisine lombarde depuis la Renaissance."),
        Question(30109, "En quel pays la paella, un mélange de riz et de fruits de mer, est-elle originaire ?", listOf("Portugal", "Italie", "Espagne", "Grèce"), 2, "Gastronomie", Difficulty.MEDIUM, explanation = "La paella est un plat traditionnel de la région de Valence, en Espagne, où le riz est cultivé depuis l'époque médiévale."),
        Question(30110, "Quel est le plat éthiopien traditionnel servi sur du pain plat (injera) ?", listOf("Mofongo", "Doro Wat", "Jollof Rice", "Moqueca"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Le Doro Wat est un ragoût de poulet épicé, considéré comme le plat national éthiopien, traditionnellement servi sur une grande crêpe fermentée appelée injera."),
        Question(30111, "En quel pays le couscous est-il le plat traditionnel principal ?", listOf("Égypte", "Maroc", "Libye", "Irak"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Le couscous est un plat emblématique du Maghreb, et le Maroc en a fait son plat national, bien qu'il soit aussi traditionnel en Algérie et en Tunisie."),
        Question(30112, "Quel est le plat libanais traditionnel à base de pois chiches et de tahin ?", listOf("Falafel", "Hummus", "Tabbouleh", "Kibbeh"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Le houmous est une purée de pois chiches mélangée à de la crème de sésame (tahin), de l'huile d'olive et du citron, un plat emblématique du Liban et du Moyen-Orient."),
        Question(30113, "En quel pays la kimchi (légumes fermentés) est-elle un accompagnement traditionnel à chaque repas ?", listOf("Japon", "Chine", "Corée du Sud", "Vietnam"), 2, "Gastronomie", Difficulty.MEDIUM, explanation = "Le kimchi est un plat national sud-coréen, préparé avec du chou fermenté et des épices, servi systématiquement en accompagnement à tous les repas."),
        Question(30114, "Quel plat indien blanc à base de riz, lentilles et épices est populaire dans le sud ?", listOf("Dosa", "Idli", "Uttapam", "Puri"), 1, "Gastronomie", Difficulty.HARD, explanation = "L'idli est un gâteau de riz et de lentilles fermenté, cuit à la vapeur, originaire du sud de l'Inde où il est un petit-déjeuner courant."),
        Question(30115, "En quel pays le pad thai (nouilles sautées) est-il le plat national ?", listOf("Malaisie", "Vietnam", "Thaïlande", "Laos"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le pad thai est un plat de nouilles de riz sauté popularisé dans les années 1930-40 en Thaïlande dans le cadre d'une campagne nationaliste, devenant un symbole culinaire du pays."),
        Question(30116, "Quel est le plat français traditionnel à base de escargots cuisinés avec du beurre, de l'ail et du persil ?", listOf("Crêpes", "Escargots à la Bourguignonne", "Pot-au-feu", "Blanquette"), 1, "Gastronomie", Difficulty.HARD, explanation = "Les escargots à la Bourguignonne sont une spécialité de la région de Bourgogne, où ils sont préparés avec du beurre, de l'ail et du persil avant d'être cuits au four."),
        Question(30117, "En quel pays le jerk chicken (poulet épicé) est-il une spécialité culinaire ?", listOf("Trinité-et-Tobago", "Haïti", "Jamaïque", "Barbade"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le jerk chicken est originaire de Jamaïque, où il est mariné avec un mélange d'épices appelé jerk, puis grillé traditionnellement sur du bois de piment."),
        Question(30118, "Quel est le plat marocain traditionnel à base de viande, fruits secs et épices cuits lentement ?", listOf("Couscous", "Tajine", "Pastilla", "Msemmen"), 1, "Gastronomie", Difficulty.HARD, explanation = "Le tajine tire son nom du plat en terre cuite dans lequel il cuit lentement, permettant aux viandes, fruits secs et épices de mijoter pour développer des saveurs riches et complexes."),
        Question(30119, "En quel pays la poutine (frites, sauce brune et fromage) est-elle une spécialité locale ?", listOf("États-Unis", "Canada", "Australie", "Nouvelle-Zélande"), 1, "Gastronomie", Difficulty.EXPERT, explanation = "La poutine est originaire du Québec, une province du Canada, où elle a été créée dans les années 1950. Ce plat combine frites, sauce brune et fromage en grains."),
        Question(30120, "Quel est le plat turc traditionnel à base de viande grillée dans du pain pita ?", listOf("Kebab", "Döner", "Lahmacun", "Tandir"), 1, "Gastronomie", Difficulty.EXPERT, explanation = "Le döner est préparé avec de la viande (agneau, bœuf ou poulet) cuite à la verticale sur une broche, puis tranchée finement et servie dans du pain pita."),
        Question(30121, "En quel pays la poke (poisson cru dés avec sauce) est-elle originaire ?", listOf("Samoa", "Fidji", "Hawaii", "Nouvelle-Zélande"), 2, "Gastronomie", Difficulty.EXPERT, explanation = "La poke est un plat traditionnel hawaïen à base de poisson cru mariné, ancré dans la culture polynésienne de l'archipel."),
        Question(30122, "Quel est le plat sénégalais traditionnel à base de riz et de poisson fumé ?", listOf("Jollof Rice", "Thieboudienne", "Mafe", "Ceebu Jën"), 2, "Gastronomie", Difficulty.EXPERT, explanation = "Le mafé est un plat d'origine malienne, à base de riz et de poisson fumé, mais il est souvent associé au Sénégal."),
        Question(30123, "En quel pays la bouillabaisse (soupe de poisson méditerranéenne) est-elle originaire ?", listOf("Italie", "Espagne", "France (Provence)", "Croatie"), 2, "Gastronomie", Difficulty.EXPERT, explanation = "La bouillabaisse est un plat traditionnel de la cuisine provençale, originaire de Marseille, en France."),
        Question(30124, "Quel est le plat péruvien traditionnel à base de poisson cru mariné dans le citron ?", listOf("Ceviche", "Lomo Saltado", "Causa Limeña", "Aji de Gallina"), 0, "Gastronomie", Difficulty.EXPERT, explanation = "Le ceviche est un plat emblématique du Pérou, où le poisson cru est mariné dans du jus de citron vert, ce qui le cuit chimiquement. Il est souvent accompagné d'oignon, de piment et de maïs."),
        Question(30125, "En quel pays le bibimbap (riz mélangé avec légumes et œuf) est-il un plat populaire ?", listOf("Japon", "Corée du Sud", "Chine", "Vietnam"), 1, "Gastronomie", Difficulty.EXPERT, explanation = "Le bibimbap est un plat emblématique de la cuisine coréenne, originaire de la Corée du Sud, où il est traditionnellement servi dans un bol de pierre chaude."),

        // CINÉMA (30126-30150)
        Question(30126, "En quel pays Bollywood, l'industrie cinématographique majeure, est-elle basée ?", listOf("Pakistan", "Inde", "Bangladesh", "Népal"), 1, "Cinéma", Difficulty.EASY, explanation = "Bollywood est le nom donné à l'industrie du cinéma en langue hindi, basée à Bombay (Mumbai), en Inde."),
        Question(30127, "Quel est le studio d'animation japonais connu pour \"Le Château Ambulant\" et \"Le Voyage de Chihiro\" ?", listOf("Madhouse", "Kyoto Animation", "Studio Ghibli", "A-1 Pictures"), 2, "Cinéma", Difficulty.EASY, explanation = "Le Studio Ghibli, fondé par Hayao Miyazaki et Isao Takahata, est célèbre pour ses chefs-d'œuvre d'animation comme \"Le Voyage de Chihiro\" (2001) et \"Le Château Ambulant\" (2004)."),
        Question(30128, "En quel pays Nollywood, l'industrie cinématographique nigériane, produit-elle des films ?", listOf("Cameroun", "Nigeria", "Ghana", "Kenya"), 1, "Cinéma", Difficulty.EASY, explanation = "Nollywood est le nom donné à l'industrie cinématographique du Nigeria, par analogie avec Hollywood et Bollywood. Le terme combine \"Nigeria\" et \"Hollywood\"."),
        Question(30129, "Quel réalisateur français est connu pour des films comme \"Amélie\" ?", listOf("Luc Besson", "Jean-Pierre Jeunet", "Michel Gondry", "Denis Villeneuve"), 1, "Cinéma", Difficulty.EASY, explanation = "Jean-Pierre Jeunet a réalisé \"Le Fabuleux Destin d'Amélie Poulain\" en 2001, film emblématique du cinéma français."),
        Question(30130, "En quel pays la \"Nouvelle Vague\" (French New Wave) du cinéma a-t-elle pris naissance ?", listOf("Italie", "France", "Allemagne", "Espagne"), 1, "Cinéma", Difficulty.EASY, explanation = "Le mouvement cinématographique de la Nouvelle Vague est né en France dans les années 1950-1960, porté par des réalisateurs comme François Truffaut et Jean-Luc Godard."),
        Question(30131, "Quel réalisateur italien est connu pour ses films en noir et blanc comme \"La Dolce Vita\" ?", listOf("Bernardo Bertolucci", "Federico Fellini", "Sergio Leone", "Vittorio de Sica"), 1, "Cinéma", Difficulty.EASY, explanation = "Federico Fellini est un maître du cinéma italien, célèbre pour son style onirique et ses films en noir et blanc, dont \"La Dolce Vita\" (1960), qui a marqué l'histoire du cinéma."),
        Question(30132, "Quel pays est le centre du cinéma d'animation avec des studios prestigieux ?", listOf("Royaume-Uni", "Japon", "Suède", "Pays-Bas"), 1, "Cinéma", Difficulty.EASY, explanation = "Le Japon est le berceau de studios d'animation de renommée mondiale comme Studio Ghibli, Toei Animation et Madhouse, qui ont produit des œuvres emblématiques du cinéma d'animation."),
